UPDATE preferences SET value = json_quote('tokyo-night') WHERE scope = 'theme' AND key = 'selected' AND json_extract(value, '$') = 't3-chat' AND EXISTS (SELECT 1 FROM themes WHERE id = 't3-chat' AND builtin = 1);
